284-  if (f.tags !== undefined) await page.getByTestId('person-form-tags').fill(f.tags);
285-}
286-
287-/** Add a person through the form. The new row's id, or null when the form refused. */
288-export async function addPerson(page: Page, f: PersonFields & { name: string; grade: string }): Promise<string | null> {
289-  const before = await ids(rows(page), 'person-row-');
290-  await fillPersonForm(page, f);
291-  await page.getByTestId('person-form-submit').click();
292-  let added: string | null = null;
293-  const ok = await until(page, async () => (added = await addedPerson(page, before, f.name)) !== null,
294-    page.getByTestId('person-form-error'), 'add person');
295-  return ok ? added : null;
296-}
297-
298-export async function editOpen(page: Page, personId: string): Promise<void> {
299-  await page.getByTestId(`person-edit-${personId}`).click();
300-  await expect(page.getByTestId('person-form-name')).not.toHaveValue('', { timeout: WAIT });
301-  editing.set(page, personId);
302-}
303-
304-/**
305- * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
306- * the grade the row shows once saved: by default the grade entered, but a grade dated from another
307- * day may leave the grade in force on the sheet's today unchanged.
308- */
309-export async function editSave(page: Page, f: PersonFields, shows: string | undefined = f.grade): Promise<boolean> {
310-  const id = editing.get(page);
--
